+/// Opcode bits 27-25 = 000: BX, multiplies, SWP, halfword transfers, PSR transfer and ALU ops
+/// share this space (gbatek: ARM Instruction Summary).
+fn execute_group_zero(cpu: &mut Cpu, bus: &mut Bus, opcode: u32) -> u32 {
