+}
+
+/// Take the Undefined Instruction exception (gbatek: ARM CPU Exceptions).
+fn undefined_instruction(cpu: &mut Cpu) -> u32 {
+    cpu.enter_exception(Exception::UndefinedInstruction);
+    0
