+        cpu.registers[0] = IWRAM;
+        execute_arm(&mut cpu, &mut bus, 0xE8A0_0000); // STMIA R0!,{} stores PC+12, base += 0x40
+        assert_eq!(bus.read32(IWRAM), 0x0800_000C);
+        assert_eq!(cpu.registers[0], IWRAM + 0x40);
