+        cpu.registers[1] = IWRAM + 0xF8;
+        execute_arm(&mut cpu, &mut bus, 0xE8B1_0006); // LDMIA R1!,{R1,R2}: no write-back
+        assert_eq!((cpu.registers[1], cpu.registers[2]), (IWRAM + 0x100, 0x11));
+    }
