+    #[test]
+    fn branch_link_and_exchange() {
+        let (mut cpu, mut bus) = setup();
+        execute_arm(&mut cpu, &mut bus, 0xEBFF_FFFE); // BL to self
+        assert_eq!(cpu.registers[14], 0x0800_0004);
